public static Connection UseConnection(string endpoint)
{
    var component = HookedComponent.RequireCurrent();
    var handle = component.GetHook<ConnectionHook>(() => new ConnectionHook(endpoint));

    if (handle.Endpoint != endpoint)
    {
        handle.Reconnect(endpoint);
    }

    return handle.Connection;
}

protected void UseConnection(string endpoint)
{
    Effect(() =>
    {
        var connection = Connect(endpoint);
        return () => connection.Dispose();
    }, [endpoint]);
}

